CREATE TABLE IF NOT EXISTS wl_talk_alias (id TEXT PRIMARY KEY, alias TEXT NOT NULL UNIQUE COLLATE NOCASE, at REAL NOT NULL);
CREATE TRIGGER IF NOT EXISTS wl_web_talk_alias_i AFTER INSERT ON wl_talk_alias WHEN NOT EXISTS (SELECT 1 FROM wl_mute) BEGIN INSERT INTO wl_change(tbl, pk, op, at, origin, tx) VALUES ('talk_alias', json_array(NEW."id"), 'up', CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER), 'web', (SELECT tx FROM wl_tx LIMIT 1)); END;
CREATE TRIGGER IF NOT EXISTS wl_web_talk_alias_u AFTER UPDATE ON wl_talk_alias WHEN NOT EXISTS (SELECT 1 FROM wl_mute) BEGIN INSERT INTO wl_change(tbl, pk, op, at, origin, tx) VALUES ('talk_alias', json_array(OLD."id"), 'up', CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER), 'web', (SELECT tx FROM wl_tx LIMIT 1)); INSERT INTO wl_change(tbl, pk, op, at, origin, tx) SELECT 'talk_alias', json_array(NEW."id"), 'up', CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER), 'web', (SELECT tx FROM wl_tx LIMIT 1) WHERE json_array(NEW."id") IS NOT json_array(OLD."id"); END;
CREATE TRIGGER IF NOT EXISTS wl_web_talk_alias_d AFTER DELETE ON wl_talk_alias WHEN NOT EXISTS (SELECT 1 FROM wl_mute) BEGIN INSERT INTO wl_change(tbl, pk, op, at, origin, tx) VALUES ('talk_alias', json_array(OLD."id"), 'del', CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER), 'web', (SELECT tx FROM wl_tx LIMIT 1)); END;
